const triage = $input.first().json.body.triage || {};
const testData = $input.first().json.body.raw || {};

const summary = `[Karate AI Auto-Bug] ${triage.failingEndpoint || 'Loan Origination API'} - ${triage.rootCauseSummary || 'API Regression'}`;

const description = `Automated Test Failure Detected by Karate AI Orchestrator

=======================================================
* Feature File: ${testData.feature}
* Environment: ${testData.environment} (dev=9090, test=9190)
* AI Severity: ${triage.severity || 'HIGH'}
* Root Cause: ${triage.rootCauseSummary || 'N/A'}
* HTTP Status: ${triage.httpStatus || 'N/A'}
* Recommended Resolution: ${triage.recommendedAction || 'N/A'}
=======================================================

Raw Failure Stack Snippet:
${JSON.stringify(testData.failures || [], null, 2)}

Full Excel Report: http://localhost:5050/api/reports/download/excel
`;

let mantisSeverity = 'major';
if (triage.severity === 'CRITICAL') mantisSeverity = 'crash';
else if (triage.severity === 'MEDIUM') mantisSeverity = 'minor';
else if (triage.severity === 'LOW') mantisSeverity = 'trivial';

return {
  json: {
    summary,
    description,
    category: { name: process.env.MANTIS_CATEGORY || "General" },
    project: { name: process.env.MANTIS_PROJECT_NAME || "BeyondLO" },
    severity: { name: mantisSeverity },
    priority: { name: "high" },
    reproducibility: { name: "always" }
  }
};
